fn model_after(b_m: V, b_o: V) -> V {
    (|| -> V {
let s = b_o.clone();
{ let mut bs: Vec<V> = Vec::new(); if pat_match(&Pat::Con(0, &[]), &s, &mut bs) { return b_m.clone(); } }
{ let mut bs: Vec<V> = Vec::new(); if pat_match(&Pat::Con(1, &[Pat::Bind]), &s, &mut bs) { let mut it = bs.into_iter(); let b_t = it.next().expect("binder"); return model_put(b_m.clone(), b_t.clone(), V::Bool(false)); } }
panic!("non-exhaustive match")
})()
}

