{ let mut bs: Vec<V> = Vec::new(); if pat_match(&Pat::Con(1, &[Pat::Bind]), &s, &mut bs) { let mut it = bs.into_iter(); let b_t = it.next().expect("binder"); return V::Bool(V::compare(&b_t.clone(), &V::Fixed(F::U8, 8i128), "<").truthy() && model_mem(b_m.clone(), b_t.clone()).truthy()); } }
